using System;
using System.Collections;
using System.IO;
using System.Linq;
using System.Net;
using System.Text;
using System.Threading;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.SceneManagement;
using FishSandbox;
using Newtonsoft.Json.Linq;
public class RecoveryGiftPanel : MonoBehaviour {
 public static bool IsOpen; public static RecoveryGiftPanel Instance;
#if RECOVERY_UNITY_PROJECT
 public const int Port=6097; const string EvidenceFolder="EditorRuntime";
#else
 public const int Port=6096; const string EvidenceFolder="Runtime";
#endif
 Vector2 scroll;string search="",group="全部",result="",state="等待本地礼物模块…";GiftDefinition selected;float duration,number;int quantity=1;string fish="random",numberText="1";bool sending;float pollAt;GUIStyle label,small,title,button,field;Font font;int lastToggleFrame=-1;
 public static string EvidencePath=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Evidence/"+EvidenceFolder));
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]public static void Install(){if(UnityEngine.SceneManagement.SceneManager.GetActiveScene().name=="OriginalArtReview")return;if(Instance)return;var o=new GameObject("Recovered original gift controls");DontDestroyOnLoad(o);Instance=o.AddComponent<RecoveryGiftPanel>();SceneManager.sceneLoaded+=OnSceneLoaded;OnSceneLoaded(SceneManager.GetActiveScene(),LoadSceneMode.Single);Application.runInBackground=true;Directory.CreateDirectory(EvidencePath);Debug.Log("[Recovery] Original gameplay with isolated recovery extension; saves="+RecoveryIsolation.PersistentDataPath);}
 static void OnSceneLoaded(Scene s,LoadSceneMode mode){foreach(var creator in UnityEngine.Object.FindObjectsByType<HeathenEngineering.SteamworksIntegration.SteamworksCreator>(FindObjectsInactive.Include,FindObjectsSortMode.None)){creator.enabled=false;}Debug.Log("[Recovery] Loaded original scene "+s.name);}
 public bool IsSending=>sending;public string LastResponse=>result;
 void Start(){Select(GiftCatalog.All[0]);if(Environment.GetCommandLineArgs().Contains("-recovery-smoke"))StartCoroutine(Smoke());}
 void Update(){if(Keyboard.current!=null&&Keyboard.current.f8Key.wasPressedThisFrame)ToggleKey();if(Time.unscaledTime>pollAt){pollAt=Time.unscaledTime+1;ThreadPool.QueueUserWorkItem(_=>{try{state=Get("/api/state");}catch{state="礼物模块未连接 ("+Port+")";}});} }
 void LateUpdate(){if(IsOpen){Cursor.lockState=CursorLockMode.None;Cursor.visible=true;}}
 public void SetOpen(bool open){IsOpen=open;if(GameInfo.Input)PlayerCamera.ToggleMouse(open);else{Cursor.lockState=CursorLockMode.None;Cursor.visible=true;}}
 string Get(string path){var req=(HttpWebRequest)WebRequest.Create("http://127.0.0.1:"+Port+path);req.Timeout=2500;using(var response=req.GetResponse())using(var reader=new StreamReader(response.GetResponseStream()))return reader.ReadToEnd();}
 public void Trigger(string id,string body){if(sending)return;sending=true;ThreadPool.QueueUserWorkItem(_=>{try{var bytes=Encoding.UTF8.GetBytes(body);var req=(HttpWebRequest)WebRequest.Create("http://127.0.0.1:"+Port+"/api/"+id);req.Method="POST";req.ContentType="application/json";req.Timeout=5000;req.ContentLength=bytes.Length;using(var stream=req.GetRequestStream())stream.Write(bytes,0,bytes.Length);using(var response=req.GetResponse())using(var reader=new StreamReader(response.GetResponseStream()))result=reader.ReadToEnd();}catch(Exception e){result=e.Message;}finally{sending=false;}});}
 void Select(GiftDefinition d){selected=d;duration=d.duration>0?d.duration:8;number=d.value;numberText=number.ToString(System.Globalization.CultureInfo.InvariantCulture);quantity=1;}
 public void StartLocal(string name=null){if(Server.Instance){result="已在原作单机世界中";return;}SaveManager.CreateServer(name??("Recovery"+DateTime.Now.ToString("MMddHHmmss")),false,false,Difficulty.Default);ConnectionManager.Instance.CreateOfflineLobby();SetOpen(false);}
 void Styles(){if(label!=null)return;var fonts=Resources.Load<RecoveryLocalizationData>("RecoveryLocalization");font=fonts?fonts.consoleFont:null;if(!font)font=Font.CreateDynamicFontFromOSFont(new[]{"Microsoft YaHei","Arial"},18);label=new GUIStyle(GUI.skin.label){font=font,fontSize=20,wordWrap=true};small=new GUIStyle(label){fontSize=16};title=new GUIStyle(label){fontSize=25,fontStyle=FontStyle.Bold};button=new GUIStyle(GUI.skin.button){font=font,fontSize=20};field=new GUIStyle(GUI.skin.textField){font=font,fontSize=18};}
 void ToggleKey(){if(lastToggleFrame==Time.frameCount)return;lastToggleFrame=Time.frameCount;SetOpen(!IsOpen);Debug.Log("[Recovery] F8 panel="+IsOpen);}
 void OnGUI(){if(Event.current.type==EventType.KeyDown&&Event.current.keyCode==KeyCode.F8){ToggleKey();Event.current.Use();}Styles();var old=GUI.matrix;float scale=Mathf.Min(Screen.width/1600f,Screen.height/900f);GUI.matrix=Matrix4x4.Scale(new Vector3(scale,scale,1));if(!IsOpen){if(GUI.Button(new Rect(1320,18,260,40),"礼物控制台 [ F8 ]",button))SetOpen(true);GUI.matrix=old;return;}var savedColor=GUI.color;GUI.color=new Color(.045f,.075f,.095f,.97f);GUI.DrawTexture(new Rect(900,10,690,880),Texture2D.whiteTexture);GUI.color=savedColor;GUI.Label(new Rect(925,25,590,38),"HOW TO FISH · 礼物控制台",title);if(GUI.Button(new Rect(1530,27,40,34),"×",button))SetOpen(false);GUI.Label(new Rect(925,65,630,35),"原作场景与玩法 · 56 个原插件事件 · F8 返回游戏",small);if(!Server.Instance&&GUI.Button(new Rect(925,104,630,36),"开始原作单机游戏（独立存档）",button))StartLocal();search=GUI.TextField(new Rect(925,148,630,32),search,field);string[] cats={"全部","钓鱼","增益","整蛊","移动","状态","召唤","船只","战斗","视觉"};for(int i=0;i<cats.Length;i++)if(GUI.Button(new Rect(925+i%5*127,190+i/5*34,120,28),cats[i],button)){group=cats[i];scroll=Vector2.zero;}
 var list=GiftCatalog.All.Where(x=>(group=="全部"||x.group==group)&&(search==""||x.name.Contains(search)||x.id.IndexOf(search,StringComparison.OrdinalIgnoreCase)>=0)).ToArray();scroll=GUI.BeginScrollView(new Rect(925,265,630,270),scroll,new Rect(0,0,605,list.Length*45));for(int i=0;i<list.Length;i++)if(GUI.Button(new Rect(0,i*45,600,40),list[i].name,button))Select(list[i]);GUI.EndScrollView();if(selected!=null){GUI.Label(new Rect(925,545,630,30),selected.name,title);GUI.Label(new Rect(925,583,630,45),selected.description,label);GUI.Label(new Rect(925,638,180,25),"时间（秒）："+duration.ToString("0"),small);duration=GUI.HorizontalSlider(new Rect(1115,647,430,20),duration,1,120);GUI.Label(new Rect(925,675,180,25),"数值："+number.ToString("0.##"),small);numberText=GUI.TextField(new Rect(1115,673,120,30),numberText,field);if(float.TryParse(numberText,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out float v))number=v;GUI.Label(new Rect(1250,675,90,25),"数量："+quantity,small);quantity=Mathf.RoundToInt(GUI.HorizontalSlider(new Rect(1350,683,195,20),quantity,1,3));fish=GUI.TextField(new Rect(925,711,320,30),fish,field);GUI.enabled=!sending;if(GUI.Button(new Rect(1260,710,285,40),sending?"发送中…":"触发 "+selected.name,button))Trigger(selected.id,Body(selected.id));GUI.enabled=true;}
 GUI.Label(new Rect(925,762,630,48),FriendlyResult(),small);GUI.Label(new Rect(925,812,630,65),FriendlyState(),small);GUI.matrix=old;}

 string FriendlyResult(){if(string.IsNullOrEmpty(result))return "先选择礼物，再点击触发。武器、鱼和首领类礼物需要对应对象。";try{var j=JObject.Parse(result);return (bool?)j["ok"]==true?"礼物已发送，执行结果见下方状态。":(string)j["error"]??result;}catch{return result;}}
 string FriendlyState(){try{var j=JObject.Parse(state);if((bool?)j["inWorld"]!=true)return "礼物模块已连接 · 进入存档后即可触发";string error=(string)j["lastError"];string last=(string)j["lastEvent"];var gift=GiftCatalog.All.FirstOrDefault(g=>g.id==last);return "生命 "+j["health"]+"  ·  饱食 "+j["fullness"]+"  ·  金币 "+j["money"]+"  ·  已执行 "+j["eventCount"]+" 次\n"+(string.IsNullOrEmpty(error)?(gift==null?"已准备就绪":"最近执行："+gift.name):"未生效："+error);}catch{return state;}}
 string Body(string id){string parameter=id.StartsWith("money/")||id=="player/heal"||id=="player/damage"||id=="player/feed"||id=="player/hunger"||id=="bait/refill"?"amount":id=="loot/next_heavy_fish"?"weightMultiplier":id=="economy/next_sale_boost"?"payoutMultiplier":id=="fishing/slow_bite"?"delayMultiplier":id=="boss/heal"?"healPercent":id=="chaos/spawn_giant_fish"||id=="chaos/spawn_tiny_fish"?"scale":id=="chaos/dynamite"?"fuseSeconds":id=="visual/slow_motion"||id=="visual/speed_up"?"timeScale":"multiplier";return "{\"durationSeconds\":"+Mathf.RoundToInt(duration)+",\""+parameter+"\":"+number.ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"count\":"+quantity+",\"uses\":"+quantity+",\"birdCount\":"+quantity+",\"fish\":\""+fish.Replace("\"","")+"\",\"item\":\""+fish.Replace("\"","")+"\",\"force\":\"strong\",\"direction\":\""+(id=="chaos/launch"?"up":"forward")+"\",\"torque\":\"strong\",\"density\":\"heavy\",\"colour\":\"red\",\"cookLevel\":\"cooked\"}";}
 IEnumerator Smoke(){yield return new WaitForSecondsRealtime(4);StartLocal("Verify"+DateTime.Now.ToString("HHmmss"));float until=Time.realtimeSinceStartup+55;while((!Player.LocalPlayer||!Server.Instance)&&Time.realtimeSinceStartup<until)yield return null;yield return new WaitForSecondsRealtime(15);if(Environment.GetCommandLineArgs().Contains("-recovery-fishing"))yield return StartCoroutine(gameObject.AddComponent<RecoveryFishingVerification>().Run());if(Environment.GetCommandLineArgs().Contains("-recovery-verify")) yield return StartCoroutine(gameObject.AddComponent<RecoveryVerification>().Run());SetOpen(false);File.WriteAllText(Path.Combine(EvidencePath,"state.txt"),"scene="+SceneManager.GetActiveScene().name+"\nplayer="+(Player.LocalPlayer!=null)+"\nserver="+(Server.Instance!=null)+"\nsaves="+RecoveryIsolation.PersistentDataPath+"\n");yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.Combine(EvidencePath,"original-world.png"));yield return new WaitForSecondsRealtime(1);SetOpen(true);yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.Combine(EvidencePath,"gift-panel.png"));yield return new WaitForSecondsRealtime(2);Debug.Log("[Recovery] SMOKE_CAPTURE_COMPLETE");if(Environment.GetCommandLineArgs().Contains("-recovery-exit"))Application.Quit();}
}



